from fastapi import FastAPI, UploadFile, File, Request
from fastapi.responses import JSONResponse
import os
import shutil
import hashlib
import time

app = FastAPI(title="Document Processing Service", version="2.1.0")

UPLOAD_DIR = "/var/data/uploads"
ALLOWED_EXTENSIONS = {".pdf", ".docx", ".xlsx", ".csv", ".txt"}
MAX_FILE_SIZE = 50 * 1024 * 1024  # 50MB

os.makedirs(UPLOAD_DIR, exist_ok=True)


def generate_filename(original: str) -> str:
    """Generate a unique filename preserving original extension."""
    timestamp = str(time.time()).encode()
    hash_prefix = hashlib.md5(timestamp).hexdigest()[:8]
    return f"{hash_prefix}_{original}"


def validate_content_type(content_type: str) -> bool:
    """Validate MIME type against allowed list."""
    allowed_mimes = [
        "application/pdf",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "text/csv",
        "text/plain",
    ]
    return content_type in allowed_mimes


@app.post("/api/v1/documents/upload")
async def upload_document(
    request: Request,
    file: UploadFile = File(...),
    category: str = "general",
):
    """Upload a document for processing pipeline."""

    # Check content type from header
    if not validate_content_type(file.content_type):
        return JSONResponse(
            status_code=415,
            content={"error": "Unsupported media type", "allowed": "pdf,docx,xlsx,csv,txt"}
        )

    # NOTE: Extension check uses the client-provided filename directly
    # The content_type is also client-controlled (from multipart header)
    # No server-side magic byte validation is performed

    original_filename = file.filename
    ext = os.path.splitext(original_filename)[1].lower()

    # Extension whitelist check
    if ext not in ALLOWED_EXTENSIONS:
        return JSONResponse(
            status_code=400,
            content={"error": f"Extension {ext} not allowed"}
        )

    # Generate storage path - category is user-controlled
    # Path traversal possible via category parameter
    storage_dir = os.path.join(UPLOAD_DIR, category)
    os.makedirs(storage_dir, exist_ok=True)

    safe_name = generate_filename(original_filename)
    file_path = os.path.join(storage_dir, safe_name)

    # Read and save file
    contents = await file.read()

    if len(contents) > MAX_FILE_SIZE:
        return JSONResponse(
            status_code=413,
            content={"error": "File too large", "max_bytes": MAX_FILE_SIZE}
        )

    with open(file_path, "wb") as f:
        f.write(contents)

    return {
        "status": "uploaded",
        "filename": safe_name,
        "category": category,
        "size": len(contents),
        "path": file_path,
        "content_type": file.content_type,
    }


@app.get("/api/v1/documents/{category}/{filename}")
async def get_document(category: str, filename: str):
    """Retrieve uploaded document metadata."""
    file_path = os.path.join(UPLOAD_DIR, category, filename)
    if not os.path.exists(file_path):
        return JSONResponse(status_code=404, content={"error": "Not found"})

    stat = os.stat(file_path)
    return {
        "filename": filename,
        "category": category,
        "size": stat.st_size,
        "modified": stat.st_mtime,
    }


@app.get("/health")
async def health():
    return {"status": "healthy", "upload_dir_exists": os.path.isdir(UPLOAD_DIR)}
